export function machine(e){if(language==='pl')return e;const [name,area,steps,tip]=english[e.id];return {...e,name,short:name,area,steps,tip:tip||'Choose a load that allows you to control the whole movement.'}}
export const translationCoverage={keys:Object.keys(pairs),machineIds:Object.keys(english)};
